-- 테스트용 가짜 데이터만 지우기 (DB 담당 DB_주문관리_변경사항 8장 그대로). 실제 데이터와 재고는 남는다
USE `aa_battery_inspection`;
-- MySQL Workbench의 안전 모드(키 없는 DELETE 막기)를 이 스크립트 동안만 끔
SET @OLD_SQL_SAFE_UPDATES = @@SQL_SAFE_UPDATES;
SET SQL_SAFE_UPDATES = 0;

-- 라인 가짜 데이터
DELETE FROM visual_defects WHERE visual_inspection_id IN (SELECT visual_inspection_id FROM visual_inspections WHERE cycle_id IN (SELECT b.cycle_id FROM battery_cycles b JOIN runs r ON r.run_id = b.run_id WHERE r.source_run_id IN ('20261110-140500-fa01', '20261112-102000-fa02', '20261113-154000-fa03', '20261114-110000-fa04', '20261116-133000-fa05', '20261117-101500-fa06', '20261118-091000-fa07')));
DELETE FROM visual_inspections WHERE cycle_id IN (SELECT b.cycle_id FROM battery_cycles b JOIN runs r ON r.run_id = b.run_id WHERE r.source_run_id IN ('20261110-140500-fa01', '20261112-102000-fa02', '20261113-154000-fa03', '20261114-110000-fa04', '20261116-133000-fa05', '20261117-101500-fa06', '20261118-091000-fa07'));
DELETE FROM electrical_tests WHERE cycle_id IN (SELECT b.cycle_id FROM battery_cycles b JOIN runs r ON r.run_id = b.run_id WHERE r.source_run_id IN ('20261110-140500-fa01', '20261112-102000-fa02', '20261113-154000-fa03', '20261114-110000-fa04', '20261116-133000-fa05', '20261117-101500-fa06', '20261118-091000-fa07'));
DELETE FROM equipment_events WHERE run_id IN (SELECT run_id FROM runs WHERE source_run_id IN ('20261110-140500-fa01', '20261112-102000-fa02', '20261113-154000-fa03', '20261114-110000-fa04', '20261116-133000-fa05', '20261117-101500-fa06', '20261118-091000-fa07'));
DELETE FROM battery_cycles WHERE run_id IN (SELECT run_id FROM runs WHERE source_run_id IN ('20261110-140500-fa01', '20261112-102000-fa02', '20261113-154000-fa03', '20261114-110000-fa04', '20261116-133000-fa05', '20261117-101500-fa06', '20261118-091000-fa07'));
DELETE FROM communication_logs WHERE source_run_id IN ('20261110-140500-fa01', '20261112-102000-fa02', '20261113-154000-fa03', '20261114-110000-fa04', '20261116-133000-fa05', '20261117-101500-fa06', '20261118-091000-fa07');
DELETE FROM runs WHERE source_run_id IN ('20261110-140500-fa01', '20261112-102000-fa02', '20261113-154000-fa03', '20261114-110000-fa04', '20261116-133000-fa05', '20261117-101500-fa06', '20261118-091000-fa07');
DELETE FROM grading_rules WHERE rule_version = 'v1.0-test' AND rule_id NOT IN (SELECT rule_id FROM battery_cycles WHERE rule_id IS NOT NULL);
DELETE FROM environment_readings WHERE source_reading_id LIKE 'fake-env-%';
DELETE FROM emergency_stop_events WHERE source_event_id LIKE 'fake-estop-%';

-- 주문 가짜 데이터
-- 재고: 가짜 기록으로 더했던 만큼 먼저 뺌 (실제 재고는 그대로 남음)
UPDATE stock SET stock_packs = stock_packs - COALESCE((SELECT SUM(l.delta_packs) FROM stock_log l
    WHERE l.product_id = stock.product_id AND (l.order_no IN ('BR-20261110-CGWJ', 'BR-20261110-UV9G', 'BR-20261111-PNYQ', 'BR-20261111-Y6AJ', 'BR-20261112-5WWH', 'BR-20261112-XLES', 'BR-20261112-EKUC', 'BR-20261113-V73K', 'BR-20261113-4Y88', 'BR-20261113-P7V3', 'BR-20261114-AJHH', 'BR-20261114-DSAF', 'BR-20261114-G8HX', 'BR-20261115-LF49', 'BR-20261115-TP4B', 'BR-20261116-PAHK', 'BR-20261116-UQZS', 'BR-20261116-F8JZ', 'BR-20261116-3CBP', 'BR-20261116-8QBE', 'BR-20261117-HJDH', 'BR-20261117-LSMS', 'BR-20261118-HW7T', 'BR-20261118-V25C', 'BR-20261118-RBF6', 'BR-20261118-U2AF') OR l.source_event_id IN ('fa2f916126a688a49f221144c127e351', 'fadc0b60a77e285bc8f7d896084aba68', 'fa2582e18cdc7b8eff9a2384bd2c758c', 'fa6cc1dc5aa810da365194e0e9dc31b8', 'faf2c7ec898f2d770f881cfc5ac6e785', 'fa309c93feefe4ebd9ec05dae6cc9130', 'fae349c7658ffdc8a21e25dddb957903'))), 0)
